// Flutter Nafath login
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:http/http.dart' as http;

class NafathAuth {
  static const baseUrl = 'https://api.nafath.sa/v1/api';
  final _storage = const FlutterSecureStorage();

  /// Step 1: request Nafath challenge (returns transId + random number to show user)
  Future<Map<String, dynamic>> requestLogin(String nationalId) async {
    final r = await http.post(
      Uri.parse('$baseUrl/Authorize'),
      headers: {
        'Content-Type': 'application/json',
        'APP-ID': const String.fromEnvironment('NAFATH_CLIENT_ID'),
        'APP-KEY': const String.fromEnvironment('NAFATH_CLIENT_SECRET'),
      },
      body: '{"nationalId":"$nationalId","service":"YourService"}',
    );
    if (r.statusCode != 200) throw Exception('Nafath request failed: ${r.body}');
    return {'random': r.headers['random'], 'transId': r.headers['transid']};
  }

  /// Step 2: poll status until user approves on their phone
  Future<bool> pollStatus(String transId, String nationalId) async {
    for (var i = 0; i < 30; i++) {
      await Future.delayed(const Duration(seconds: 2));
      final r = await http.get(Uri.parse('$baseUrl/MobileRequestStatus?transId=$transId&nationalId=$nationalId'));
      if (r.statusCode == 200) {
        final body = r.body.toLowerCase();
        if (body.contains('completed')) return true;
        if (body.contains('rejected') || body.contains('expired')) return false;
      }
    }
    return false;
  }
}

