// React Native Nafath login
import AsyncStorage from '@react-native-async-storage/async-storage';
import Keychain from 'react-native-keychain';

export class NafathAuth {
  static baseUrl = 'https://api.nafath.sa/v1/api';

  static async requestLogin(nationalId) {
    const r = await fetch(`${this.baseUrl}/Authorize`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'APP-ID': Config.NAFATH_CLIENT_ID,
        'APP-KEY': Config.NAFATH_CLIENT_SECRET,
      },
      body: JSON.stringify({ nationalId, service: 'YourService' }),
    });
    if (!r.ok) throw new Error(`Nafath request failed: ${r.status}`);
    return { random: r.headers.get('random'), transId: r.headers.get('transid') };
  }

  static async pollStatus(transId, nationalId) {
    for (let i = 0; i < 30; i++) {
      await new Promise(r => setTimeout(r, 2000));
      const r = await fetch(`${this.baseUrl}/MobileRequestStatus?transId=${transId}&nationalId=${nationalId}`);
      const body = (await r.text()).toLowerCase();
      if (body.includes('completed')) return true;
      if (body.includes('rejected') || body.includes('expired')) return false;
    }
    return false;
  }
}

